/**
 * Motifs for catalog modules in R07 Teknik (0.28). Same geometry format as motifs.ts.
 * Parts with their own hue use the main role (accent2 shifts the hue).
 */
import type { Motif, Part, Role } from './motifs';

const p = (d: string, r: Role, hue?: number): Part => ({ t: 'path', d, r, hue });
const c = (cx: number, cy: number, rad: number, r: Role, hue?: number): Part => ({ t: 'circle', cx, cy, rad, r, hue });
const q = (x: number, y: number, w: number, h: number, r: Role, rx = 1.5, hue?: number): Part => ({ t: 'rect', x, y, w, h, rx, r, hue });
const G = { green: 115, orange: 26, red: 6, yellow: 46, blue: 210, sky: 195, brown: 28, sand: 40, purple: 285, slate: 220 } as const;
const fig = (x: number, y: number, s: number, r: Role): Part[] => [c(x, y - 14 * s, 5 * s, r), p(`M${x - 7 * s} ${y + 12 * s} V${y - 2 * s} C${x - 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 7 * s} ${x + 7 * s} ${y - 2 * s} V${y + 12 * s} Z`, r)];
const screen = (x: number, y: number, w: number, h: number): Part[] => [q(x, y, w, h, 'main', 3), q(x + 3, y + 3, w - 6, h - 6, 'light', 1.5)];
const laptop = (x: number, y: number, w: number): Part[] => [q(x + 4, y, w - 8, w * 0.55, 'main', 3), q(x + 7, y + 3, w - 14, w * 0.55 - 6, 'light', 1), p(`M${x} ${y + w * 0.55 + 2} H${x + w} L${x + w - 4} ${y + w * 0.55 + 7} H${x + 4} Z`, 'main')];
const phone = (x: number, y: number): Part[] => [q(x, y, 22, 40, 'main', 5), q(x + 3, y + 5, 16, 28, 'light', 2), c(x + 11, y + 36, 1.5, 'light')];
const browser = (): Part[] => [q(4, 8, 56, 46, 'light', 3), q(4, 8, 56, 10, 'main', 3), ...[10, 16, 22].map((x) => c(x, 13, 1.8, 'light'))];
const gear = (x: number, y: number, r: number, role: Role = 'main', hue?: number, teeth = 8): Part[] => [p(Array.from({ length: teeth }, (_, i) => { const a = (i / teeth) * Math.PI * 2; const a1 = a - 0.18; const a2 = a + 0.18; return `${i ? 'L' : 'M'}${(x + Math.cos(a1) * r).toFixed(1)} ${(y + Math.sin(a1) * r).toFixed(1)} L${(x + Math.cos(a1) * (r + 4)).toFixed(1)} ${(y + Math.sin(a1) * (r + 4)).toFixed(1)} L${(x + Math.cos(a2) * (r + 4)).toFixed(1)} ${(y + Math.sin(a2) * (r + 4)).toFixed(1)} L${(x + Math.cos(a2) * r).toFixed(1)} ${(y + Math.sin(a2) * r).toFixed(1)}`; }).join(' ') + ' Z', role, hue), c(x, y, r * 0.4, 'light')];
const lock = (x: number, y: number, s: number, hue?: number): Part[] => [q(x - 12 * s, y, 24 * s, 20 * s, 'main', 3, hue), p(`M${x - 7 * s} ${y} V${y - 6 * s} C${x - 7 * s} ${y - 14 * s} ${x + 7 * s} ${y - 14 * s} ${x + 7 * s} ${y - 6 * s} V${y}`, 'line'), c(x, y + 9 * s, 2.6 * s, 'light')];
const bolt = (x: number, y: number, s = 1): Part => p(`M${x + 2 * s} ${y - 10 * s} L${x - 6 * s} ${y + 2 * s} H${x} L${x - 2 * s} ${y + 10 * s} L${x + 6 * s} ${y - 2 * s} H${x} Z`, 'main', G.yellow);
const wheel = (x: number, y: number, r: number): Part[] => [c(x, y, r, 'line'), c(x, y, r * 0.35, 'main', G.slate)];
const car = (x: number, y: number, s: number, hue: number = G.red): Part[] => [p(`M${x - 22 * s} ${y + 6 * s} V${y - 2 * s} L${x - 14 * s} ${y - 4 * s} L${x - 8 * s} ${y - 12 * s} H${x + 10 * s} L${x + 16 * s} ${y - 4 * s} L${x + 22 * s} ${y - 2 * s} V${y + 6 * s} Z`, 'main', hue), p(`M${x - 6 * s} ${y - 10 * s} H${x} V${y - 4 * s} H${x - 11 * s} Z M${x + 3 * s} ${y - 10 * s} H${x + 9 * s} L${x + 13 * s} ${y - 4 * s} H${x + 3 * s} Z`, 'light'), c(x - 12 * s, y + 6 * s, 5 * s, 'line'), c(x + 12 * s, y + 6 * s, 5 * s, 'line')];
const train = (x: number, y: number, s: number, hue: number = G.blue): Part[] => [p(`M${x - 24 * s} ${y + 8 * s} V${y - 8 * s} C${x - 24 * s} ${y - 14 * s} ${x - 18 * s} ${y - 16 * s} ${x - 10 * s} ${y - 16 * s} H${x + 24 * s} V${y + 8 * s} Z`, 'main', hue), q(x - 16 * s, y - 12 * s, 10 * s, 8 * s, 'light', 1), q(x - 2 * s, y - 12 * s, 10 * s, 8 * s, 'light', 1), q(x + 12 * s, y - 12 * s, 10 * s, 8 * s, 'light', 1), c(x - 14 * s, y + 10 * s, 3.5 * s, 'line'), c(x + 14 * s, y + 10 * s, 3.5 * s, 'line')];
const plane = (x: number, y: number, s: number): Part[] => [p(`M${x - 26 * s} ${y} C${x - 26 * s} ${y - 4 * s} ${x + 18 * s} ${y - 5 * s} ${x + 24 * s} ${y - 2 * s} C${x + 28 * s} ${y} ${x + 24 * s} ${y + 3 * s} ${x + 18 * s} ${y + 3 * s} H${x - 22 * s} Z`, 'light'), p(`M${x - 4 * s} ${y} L${x - 14 * s} ${y + 18 * s} H${x - 6 * s} L${x + 8 * s} ${y} Z M${x - 4 * s} ${y - 2 * s} L${x - 12 * s} ${y - 16 * s} H${x - 6 * s} L${x + 6 * s} ${y - 2 * s} Z`, 'main'), p(`M${x - 24 * s} ${y - 1 * s} L${x - 28 * s} ${y - 10 * s} H${x - 22 * s} L${x - 18 * s} ${y - 2 * s} Z`, 'main')];
const wave = (y: number): Part => p(`M2 ${y} C10 ${y - 4} 14 ${y + 4} 22 ${y} C30 ${y - 4} 34 ${y + 4} 42 ${y} C50 ${y - 4} 54 ${y + 4} 62 ${y} V62 H2 Z`, 'main', G.blue);
const house = (x: number, y: number, w: number, r: Role = 'main', hue?: number): Part[] => [p(`M${x} ${y + w * 0.45} L${x + w / 2} ${y} L${x + w} ${y + w * 0.45} V${y + w * 1.1} H${x} Z`, r, hue), q(x + w * 0.38, y + w * 0.7, w * 0.24, w * 0.4, 'light', 1)];
const node = (x: number, y: number, r: number, role: Role = 'main', hue?: number): Part => c(x, y, r, role, hue);
const plus = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} H${x + 5 * s} M${x} ${y - 5 * s} V${y + 5 * s}`, 'line');
const check = (x: number, y: number, s = 1): Part => p(`M${x - 5 * s} ${y} L${x - 1 * s} ${y + 4 * s} L${x + 6 * s} ${y - 4 * s}`, 'line');
const arrowR = (x1: number, x2: number, y: number): Part => p(`M${x1} ${y} H${x2} M${x2 - 4} ${y - 4} L${x2} ${y} L${x2 - 4} ${y + 4}`, 'line');
const bubble = (x: number, y: number, w: number, h: number, r: Role): Part => p(`M${x + 4} ${y} H${x + w - 4} Q${x + w} ${y} ${x + w} ${y + 4} V${y + h - 4} Q${x + w} ${y + h} ${x + w - 4} ${y + h} H${x + 14} L${x + 6} ${y + h + 7} V${y + h} H${x + 4} Q${x} ${y + h} ${x} ${y + h - 4} V${y + 4} Q${x} ${y} ${x + 4} ${y} Z`, r);
const doc = (x: number, y: number, w: number, h: number, lines = 3): Part[] => [q(x, y, w, h, 'light', 2), p(Array.from({ length: lines }, (_, i) => `M${x + 5} ${y + 8 + i * 7} H${x + w - (i === lines - 1 ? 12 : 5)}`).join(' '), 'line')];
const brackets = (x: number, y: number, s: number): Part => p(`M${x - 4 * s} ${y - 8 * s} L${x - 12 * s} ${y} L${x - 4 * s} ${y + 8 * s} M${x + 4 * s} ${y - 8 * s} L${x + 12 * s} ${y} L${x + 4 * s} ${y + 8 * s}`, 'line');
const wifi = (x: number, y: number, s: number): Part[] => [c(x, y, 2.6 * s, 'main'), p(`M${x - 8 * s} ${y - 6 * s} C${x - 4 * s} ${y - 10 * s} ${x + 4 * s} ${y - 10 * s} ${x + 8 * s} ${y - 6 * s} M${x - 14 * s} ${y - 12 * s} C${x - 6 * s} ${y - 19 * s} ${x + 6 * s} ${y - 19 * s} ${x + 14 * s} ${y - 12 * s}`, 'line')];
const pylon = (x: number, y: number, s: number): Part => p(`M${x - 8 * s} ${y + 40 * s} L${x} ${y} L${x + 8 * s} ${y + 40 * s} M${x - 14 * s} ${y + 8 * s} H${x + 14 * s} M${x - 10 * s} ${y + 16 * s} H${x + 10 * s} M${x - 5 * s} ${y + 20 * s} L${x + 6 * s} ${y + 32 * s} M${x + 5 * s} ${y + 20 * s} L${x - 6 * s} ${y + 32 * s}`, 'line');

